test("casts over an instance of SomeItem", () => {
  const theSomeItem =
    TestCommonJsonization.loadMinimalSomeItem();

  expect(
    OurTypes.isItem(theSomeItem)
  ).toStrictEqual(true);
  expect(
    OurTypes.asItem(theSomeItem)
  ).toStrictEqual(theSomeItem);

  expect(
    OurTypes.isSomeItem(theSomeItem)
  ).toStrictEqual(true);
  expect(
    OurTypes.asSomeItem(theSomeItem)
  ).toStrictEqual(theSomeItem);

  expect(
    OurTypes.isSpecialItem(theSomeItem)
  ).toStrictEqual(false);
  expect(
    OurTypes.asSpecialItem(theSomeItem)
  ).toBeNull();

  expect(
    OurTypes.isContainer(theSomeItem)
  ).toStrictEqual(false);
  expect(
    OurTypes.asContainer(theSomeItem)
  ).toBeNull();

  expect(
    OurTypes.isWrapper(theSomeItem)
  ).toStrictEqual(false);
  expect(
    OurTypes.asWrapper(theSomeItem)
  ).toBeNull();
});

